# Construction source for #2253 r1\n# Deterministic standard-library fixture; no GUI, model, network, or runtime calls.\nfrom dataclasses import dataclass\n@dataclass(frozen=True)\nclass Event:\n    session:str; seq:int; kind:str; critical:bool\nclass Delivery:\n    def __init__(self,cap=4): self.cap=cap; self.events={}; self.overflow={}\n    def ingest(self,e):\n        q=self.events.setdefault(e.session,[])\n        if len(q)<self.cap: q.append(e); return\n        o=self.overflow.setdefault(e.session,{'first_unretained':e.seq,'count':0}); o['count']+=1\n    def package(self,s): return {'session':s,'events':[e.__dict__ for e in self.events.get(s,[])],'overflow':self.overflow.get(s)}\nif __name__=='__main__':\n    d=Delivery(); [d.ingest(Event('A',i,'FOCUS_LOST' if i==1 else 'STATE',i==1)) for i in range(1,11)]\n    assert [e['seq'] for e in d.package('A')['events']]==[1,2,3,4]\n    assert d.package('A')['overflow']=={'first_unretained':5,'count':6}\n    print('STOPPED_NO_LIVE_WATCHER_OR_MODEL')\n